def tri(n: int) -> List[int]:
    """
    Calculate the Tribonacci sequence up to the nth number and return a list of the sequence.
    """
    if n == 0:
        return [0]
    elif n == 1:
        return [1, 1]
    elif n == 2:
        return [1, 1, 1]

    tribonacci = [0, 1, 1]
    for i in range(3, n + 1):
        if i % 2 == 0:
