def minPath(grid: List[List[int]], k: int) -> List[int]:
    n = len(grid)
    all_values = [val for row in grid for val in row]

    def get_neighbors(i, j):
        neighbors = []
        if i > 0:
            neighbors.append((i-1, j))
        if i < n-1:
            neighbors.append((i+1, j))
        if j > 0:
            neighbors.append((i, j-1))
        if j < n-1:
            neighbors.append((i, j+1))
        return neighbors

    def dfs(i, j, path, visited):
        if len(path) == k:
            return path

        visited.add((i, j))
        for ni, nj in get_neighbors(i, j):
            if (ni, nj) not in visited:
                new_path = dfs(ni, nj, path + [grid[ni][nj]], visited.copy())
                if new_path:
                    return new_path

    for perm in permutations(all_values, k):
        start_i, start_j = divmod(all_values.index(perm[0]), n)
        path = dfs(start_i, start_j, [perm[0]], set())
        if path:
            return path

