    return hashlib.md5(text.encode()).hexdigest()

def change_base(x: int, base: int) -> str:
    if x < 0 or base < 2:
        return "Invalid input"

    return str(base) if x == 0 else change_base(x // base, base) + str(x % base)

def specialFilter(nums: List[int]) -> int:
