from collections import deque

def rolling_max(numbers):
    result = []
    window = deque()

    for i, num in enumerate(numbers):
        while window and numbers[window[-1]] < num:
            window.pop()
        window.append(i)

        if window[0] == i - len(window):
            window.popleft()

        result.append(numbers[window[0]])

    return result

def below_zero(operations: List[int]) -> bool:
    balance = 0
    for operation in operations:
        balance += operation
        if balance < 0:
            return True
    return False

from collections import Counter

def search(lst: List[int]) -> int:
    counter = Counter(lst)
    result = -1
    for num, freq in counter.items():
        if num > 0 and freq >= num:
            result = max(result, num)
    return result

def correct_bracketing(brackets: str) -> bool:
    stack = []
    for bracket in brackets:
        if bracket == '(':
            stack.append(bracket)
        elif bracket == ')':
            if not stack:
                return False
            stack.pop()
    return len(stack) == 0

def same_chars(s0: str, s1: str) -> bool:
    """
    Check if two words have the same characters.
    """
    # Count the characters in each string
    count_s0 = {}
    count_s1 = {}

    for char in s0:
        count_s0[char] = count_s0.get(char, 0) + 1

    for char in s1:
        count_s1[char] = count_s1.get(char, 0) + 1

    # Compare the character counts
    return count_s0 == count_s1

def correct_bracketing(brackets: str) -> bool:
    stack = []
